-- Отзыв из Telegram-чата на Temel Dental (Подгорица) + врача Ibrahim Halil Temel.
-- Автор анонимен (user_id = NULL) — в выдаче подписывается как «Аноним».
-- Доверие к источнику редакция оценила вручную, но документов мы не видели,
-- поэтому is_verified / is_pinned не трогаем: бейдж «Подтверждено документами»
-- ставится только по документам (prd/clinic-reputation/).
-- Оценка 1★ — решение редакции 2026-10-26: звёзд автор не ставил, текст
-- однозначно негативный.
--
-- Применение:
--   mysql -u root -p --default-character-set=utf8mb4 docta_me < server/sql/reviews-telegram/temel-dental-podgorica.sql

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- id клиники и врача на проде отличаются от локальных — берём по slug
SET @clinic_id = (SELECT id FROM clinics WHERE slug = 'temel-dental-podgorica');
SET @doctor_id = (SELECT id FROM doctors WHERE slug = 'ibrahim-halil-temel');

INSERT INTO reviews (
	user_id, clinic_id, doctor_id,
	provider, provider_review_id,
	rating, status, original_language, original_text,
	text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr,
	published_at
) VALUES (
	NULL, @clinic_id, @doctor_id,
	'telegram', 'tg_anon_temel_dental_20261026',
	1, 'approved', 'ru',
	-- original_text (ru)
	'После переезда из России продолжила ортодонтическое лечение в данной клинике, привезла с собой свои дуги. Зубы были ровные и всё было в порядке, несмотря на то, что была большая пауза в лечении (полгода). Врач Темел Ибрагим сказал, что завершит лечение примерно за полгода и предложил имплантироваться у него же. Во время лечения он менял дуги и лигатуры, не корректируя движение зубов. Примерно через 2 месяца он поставил импланты, хотя этого было нельзя делать, не завершив ортодонтическое лечение (но я об этом не знала). За 2 месяца до предполагаемого снятия брекетов у меня начали ехать зубы и они перестали смыкаться с одной стороны (это привело к тому, что я имею проблемы с суставом). На тот момент я уже начала сильно сомневаться в компетенции данного врача и пошла на консультацию в другую клинику. Там мне сказали, что исправить это нельзя из-за наличия имплантов. Но эта проблема решилась сама собой… Другой врач-хирург, делая тест на стабильность, вытащил имплант, а насчёт второго он сказал, что тот слишком подвижный и его тоже нужно удалять (на данный момент его уже удалили). Благодаря данной клинике мне пришлось делать наращивание кости с синус-лифтингом. После установки имплантов Темел проверил, всё ли хорошо с ними, только 1 раз, почти сразу после установки. Потом, когда я почувствовала, что один из имплантов сильно спустился и прорезал десну, я попросила его проверить, всё ли хорошо. Он сделал визуальный осмотр без снимка и сказал, что всё в порядке.\n\nЧто же с брекетами? Была попытка разговора с Темелом Ибрагимом, и она была абсолютно безуспешной. Он сказал, что якобы проблема была в дугах из России и виноват прошлый врач. На вопрос «Почему вы видели, что что-то идёт неправильно, и ничего не сделали и не говорили?» он ответил, что я якобы сама попросила его просто менять дуги, а что ему бедному оставалось. Все же мы знаем этих пациентов, которые не хотят, чтобы их профессионально лечили? И я не знаю.\n\nПроблема с имплантацией возникла уже после данного разговора, и идти снова разбираться в данную клинику вообще нет желания.\n\nВот ещё интересные моменты из лечения в данной клинике:\n— Никогда не было ортодонтического воска, если дуга кололась — её просто срезали.\n— На месте отсутствующего зуба с одной стороны стоит пластиковая трубочка, которую нужно менять на новую каждый месяц. Темел отказался её менять на протяжении всего лечения, оправдывая это тем, что якобы пластиковая трубочка не даёт зубам разъехаться. Не нужно быть ортодонтом, чтобы понять, что это ложь.\n— Темел не использовал эластики за всё время лечения. Но в самом начале он навязал доп. услугу по замене двух брекетов. Якобы они неправильные, так как на них отсутствовали крючки, на которые цепляются эластики. Но он никогда не использовал данные крючки, как и эластики в принципе. А положение брекетов изначально было правильным.',
	-- text_sr
	'Nakon preseljenja iz Rusije nastavila sam ortodontsko liječenje u ovoj klinici, ponijela sam svoje lukove sa sobom. Zubi su bili pravilni i sve je bilo u redu, iako je bila velika pauza u liječenju (pola godine). Doktor Temel Ibrahim je rekao da će završiti liječenje za otprilike pola godine i ponudio da mi implantate ugradi kod sebe. Tokom liječenja mijenjao je lukove i ligature, ne korigujući kretanje zuba. Nakon otprilike 2 mjeseca ugradio je implantate, iako se to nije smjelo raditi prije nego što se završi ortodontsko liječenje (ali ja to nisam znala). Dva mjeseca prije predviđenog skidanja aparatića zubi su počeli da se pomjeraju i prestali su da se sklapaju s jedne strane (zbog toga sada imam problem sa zglobom). U tom trenutku već sam ozbiljno počela da sumnjam u stručnost ovog doktora i otišla sam na konsultaciju u drugu kliniku. Tamo su mi rekli da se to ne može ispraviti zbog implantata. Ali taj problem se riješio sam od sebe… Drugi hirurg je, radeći test stabilnosti, izvadio implantat, a za drugi je rekao da je previše pokretan i da i njega treba izvaditi (u međuvremenu je već izvađen). Zahvaljujući ovoj klinici morala sam da radim augmentaciju kosti sa sinus liftom. Nakon ugradnje implantata Temel je samo 1 put provjerio da li je sve u redu s njima, skoro odmah nakon ugradnje. Kasnije, kada sam osjetila da je jedan od implantata jako spao i probio desni, zamolila sam ga da provjeri da li je sve u redu. Pregledao je samo vizuelno, bez snimka, i rekao da je sve u redu.\n\nA šta je sa aparatićem? Bio je pokušaj razgovora sa Temelom Ibrahimom i bio je potpuno bezuspješan. Rekao je da je problem navodno bio u lukovima iz Rusije i da je kriv prethodni doktor. Na pitanje „Zašto ste vidjeli da nešto ide pogrešno, a ništa niste uradili ni rekli?“ odgovorio je da sam ga navodno sama zamolila da samo mijenja lukove, pa šta je jadnik mogao. Pa valjda svi znamo te pacijente koji ne žele da ih liječe profesionalno? Ja ne znam.\n\nProblem sa implantatima pojavio se već nakon tog razgovora i uopšte nemam želju da ponovo idem u tu kliniku da se raspravljam.\n\nEvo još nekoliko zanimljivih detalja iz liječenja u ovoj klinici:\n— Nikada nije bilo ortodontskog voska; ako bi luk bo, jednostavno bi ga odsjekli.\n— Na mjestu zuba koji nedostaje s jedne strane stoji plastična cjevčica koju treba mijenjati novom svakog mjeseca. Temel je odbijao da je mijenja tokom cijelog liječenja, pravdajući to time da plastična cjevčica navodno ne da zubima da se razmaknu. Ne morate biti ortodont da biste shvatili da je to laž.\n— Temel nije koristio elastike tokom cijelog liječenja. Ali na samom početku nametnuo mi je dodatnu uslugu zamjene dvije bravice. Navodno su bile pogrešne, jer na njima nisu postojale kukice za koje se kače elastike. Ali te kukice nikada nije koristio, kao ni elastike uopšte. A položaj bravica je od početka bio pravilan.',
	-- text_sr_cyrl
	'Након пресељења из Русије наставила сам ортодонтско лијечење у овој клиници, понијела сам своје лукове са собом. Зуби су били правилни и све је било у реду, иако је била велика пауза у лијечењу (пола године). Доктор Темел Ибрахим је рекао да ће завршити лијечење за отприлике пола године и понудио да ми имплантате угради код себе. Током лијечења мијењао је лукове и лигатуре, не коригујући кретање зуба. Након отприлике 2 мјесеца уградио је имплантате, иако се то није смјело радити прије него што се заврши ортодонтско лијечење (али ја то нисам знала). Два мјесеца прије предвиђеног скидања апаратића зуби су почели да се помјерају и престали су да се склапају с једне стране (због тога сада имам проблем са зглобом). У том тренутку већ сам озбиљно почела да сумњам у стручност овог доктора и отишла сам на консултацију у другу клинику. Тамо су ми рекли да се то не може исправити због имплантата. Али тај проблем се ријешио сам од себе… Други хирург је, радећи тест стабилности, извадио имплантат, а за други је рекао да је превише покретан и да и њега треба извадити (у међувремену је већ извађен). Захваљујући овој клиници морала сам да радим аугментацију кости са синус лифтом. Након уградње имплантата Темел је само 1 пут провјерио да ли је све у реду с њима, скоро одмах након уградње. Касније, када сам осјетила да је један од имплантата јако спао и пробио десни, замолила сам га да провјери да ли је све у реду. Прегледао је само визуелно, без снимка, и рекао да је све у реду.\n\nА шта је са апаратићем? Био је покушај разговора са Темелом Ибрахимом и био је потпуно безуспјешан. Рекао је да је проблем наводно био у луковима из Русије и да је крив претходни доктор. На питање „Зашто сте видјели да нешто иде погрешно, а ништа нисте урадили ни рекли?“ одговорио је да сам га наводно сама замолила да само мијења лукове, па шта је јадник могао. Па ваљда сви знамо те пацијенте који не желе да их лијече професионално? Ја не знам.\n\nПроблем са имплантатима појавио се већ након тог разговора и уопште немам жељу да поново идем у ту клинику да се расправљам.\n\nЕво још неколико занимљивих детаља из лијечења у овој клиници:\n— Никада није било ортодонтског воска; ако би лук бо, једноставно би га одсјекли.\n— На мјесту зуба који недостаје с једне стране стоји пластична цјевчица коју треба мијењати новом сваког мјесеца. Темел је одбијао да је мијења током цијелог лијечења, правдајући то тиме да пластична цјевчица наводно не да зубима да се размакну. Не морате бити ортодонт да бисте схватили да је то лаж.\n— Темел није користио еластике током цијелог лијечења. Али на самом почетку наметнуо ми је додатну услугу замјене двије бравице. Наводно су биле погрешне, јер на њима нису постојале кукице за које се каче еластике. Али те кукице никада није користио, као ни еластике уопште. А положај бравица је од почетка био правилан.',
	-- text_en
	'After moving from Russia I continued my orthodontic treatment at this clinic and brought my own archwires with me. My teeth were straight and everything was fine, despite a long break in the treatment (six months). Dr. Temel Ibrahim said he would finish the treatment in about six months and offered to place the implants himself. During the treatment he changed the archwires and ligatures without correcting the movement of the teeth. After about 2 months he placed the implants, although that should not have been done before the orthodontic treatment was finished (but I did not know that). Two months before the braces were supposed to come off my teeth started shifting and stopped meeting on one side (which is why I now have a jaw joint problem). By then I had already begun to seriously doubt this doctor\'s competence and went for a consultation at another clinic. There I was told that it could no longer be corrected because of the implants. But that problem solved itself… Another surgeon pulled one implant out while doing a stability test, and said the second one was too mobile and had to be removed as well (by now it has been removed). Thanks to this clinic I had to undergo bone grafting with a sinus lift. After the implants were placed, Temel checked whether they were all right only once, almost immediately after the procedure. Later, when I felt that one of the implants had dropped badly and cut through the gum, I asked him to check whether everything was fine. He did a visual examination without an X-ray and said everything was in order.\n\nAnd what about the braces? There was an attempt to talk to Temel Ibrahim, and it was completely unsuccessful. He said the problem had supposedly been with the archwires from Russia and that the previous doctor was to blame. To the question "Why did you see that something was going wrong and do nothing and say nothing?" he answered that I had supposedly asked him myself just to change the archwires, and what else was the poor man to do. We all know those patients who don\'t want to be treated professionally, right? I don\'t.\n\nThe problem with the implants came up after that conversation, and I have no desire whatsoever to go back to this clinic and sort things out again.\n\nHere are some other interesting details from the treatment at this clinic:\n— There was never any orthodontic wax; if a wire was poking, they simply cut it off.\n— Where a tooth is missing on one side there is a plastic tube that has to be replaced with a new one every month. Temel refused to replace it for the whole course of the treatment, justifying it by claiming that the plastic tube keeps the teeth from drifting apart. You don\'t have to be an orthodontist to understand that this is a lie.\n— Temel did not use elastics at any point during the treatment. But at the very beginning he pushed an extra service on me: replacing two brackets. Supposedly they were the wrong ones, because they had no hooks for attaching elastics. But he never used those hooks, nor elastics at all. And the position of the brackets had been correct from the start.',
	-- text_ru
	'После переезда из России продолжила ортодонтическое лечение в данной клинике, привезла с собой свои дуги. Зубы были ровные и всё было в порядке, несмотря на то, что была большая пауза в лечении (полгода). Врач Темел Ибрагим сказал, что завершит лечение примерно за полгода и предложил имплантироваться у него же. Во время лечения он менял дуги и лигатуры, не корректируя движение зубов. Примерно через 2 месяца он поставил импланты, хотя этого было нельзя делать, не завершив ортодонтическое лечение (но я об этом не знала). За 2 месяца до предполагаемого снятия брекетов у меня начали ехать зубы и они перестали смыкаться с одной стороны (это привело к тому, что я имею проблемы с суставом). На тот момент я уже начала сильно сомневаться в компетенции данного врача и пошла на консультацию в другую клинику. Там мне сказали, что исправить это нельзя из-за наличия имплантов. Но эта проблема решилась сама собой… Другой врач-хирург, делая тест на стабильность, вытащил имплант, а насчёт второго он сказал, что тот слишком подвижный и его тоже нужно удалять (на данный момент его уже удалили). Благодаря данной клинике мне пришлось делать наращивание кости с синус-лифтингом. После установки имплантов Темел проверил, всё ли хорошо с ними, только 1 раз, почти сразу после установки. Потом, когда я почувствовала, что один из имплантов сильно спустился и прорезал десну, я попросила его проверить, всё ли хорошо. Он сделал визуальный осмотр без снимка и сказал, что всё в порядке.\n\nЧто же с брекетами? Была попытка разговора с Темелом Ибрагимом, и она была абсолютно безуспешной. Он сказал, что якобы проблема была в дугах из России и виноват прошлый врач. На вопрос «Почему вы видели, что что-то идёт неправильно, и ничего не сделали и не говорили?» он ответил, что я якобы сама попросила его просто менять дуги, а что ему бедному оставалось. Все же мы знаем этих пациентов, которые не хотят, чтобы их профессионально лечили? И я не знаю.\n\nПроблема с имплантацией возникла уже после данного разговора, и идти снова разбираться в данную клинику вообще нет желания.\n\nВот ещё интересные моменты из лечения в данной клинике:\n— Никогда не было ортодонтического воска, если дуга кололась — её просто срезали.\n— На месте отсутствующего зуба с одной стороны стоит пластиковая трубочка, которую нужно менять на новую каждый месяц. Темел отказался её менять на протяжении всего лечения, оправдывая это тем, что якобы пластиковая трубочка не даёт зубам разъехаться. Не нужно быть ортодонтом, чтобы понять, что это ложь.\n— Темел не использовал эластики за всё время лечения. Но в самом начале он навязал доп. услугу по замене двух брекетов. Якобы они неправильные, так как на них отсутствовали крючки, на которые цепляются эластики. Но он никогда не использовал данные крючки, как и эластики в принципе. А положение брекетов изначально было правильным.',
	-- text_de
	'Nach meinem Umzug aus Russland habe ich die kieferorthopädische Behandlung in dieser Klinik fortgesetzt und meine eigenen Bögen mitgebracht. Die Zähne waren gerade und alles war in Ordnung, obwohl es eine lange Behandlungspause gegeben hatte (ein halbes Jahr). Der Arzt Temel Ibrahim sagte, er werde die Behandlung in etwa einem halben Jahr abschließen, und bot an, die Implantate gleich bei sich zu setzen. Während der Behandlung wechselte er die Bögen und Ligaturen, ohne die Bewegung der Zähne zu korrigieren. Nach etwa 2 Monaten setzte er die Implantate, obwohl man das nicht hätte tun dürfen, solange die kieferorthopädische Behandlung nicht abgeschlossen war (aber das wusste ich nicht). Zwei Monate vor der geplanten Abnahme der Brackets begannen meine Zähne zu wandern und schlossen auf einer Seite nicht mehr zusammen (deshalb habe ich jetzt Probleme mit dem Kiefergelenk). Zu diesem Zeitpunkt hatte ich bereits starke Zweifel an der Kompetenz dieses Arztes und ging zur Beratung in eine andere Klinik. Dort sagte man mir, das lasse sich wegen der Implantate nicht mehr korrigieren. Aber dieses Problem hat sich von selbst gelöst… Ein anderer Chirurg zog bei einem Stabilitätstest ein Implantat heraus und sagte zum zweiten, es sei zu beweglich und müsse ebenfalls entfernt werden (inzwischen wurde es entfernt). Dank dieser Klinik musste ich einen Knochenaufbau mit Sinuslift machen lassen. Nach dem Setzen der Implantate hat Temel nur 1 Mal kontrolliert, ob alles in Ordnung ist, fast unmittelbar nach dem Eingriff. Als ich später merkte, dass eines der Implantate stark abgesunken war und das Zahnfleisch durchstoßen hatte, bat ich ihn zu prüfen, ob alles in Ordnung sei. Er machte eine Sichtkontrolle ohne Röntgenbild und sagte, alles sei in Ordnung.\n\nUnd was ist mit den Brackets? Es gab einen Versuch, mit Temel Ibrahim zu sprechen, und er war völlig erfolglos. Er sagte, das Problem habe angeblich an den Bögen aus Russland gelegen und der frühere Arzt sei schuld. Auf die Frage „Warum haben Sie gesehen, dass etwas falsch läuft, und nichts getan und nichts gesagt?“ antwortete er, ich hätte ihn angeblich selbst gebeten, einfach nur die Bögen zu wechseln – was blieb dem Armen denn übrig. Wir kennen ja alle diese Patienten, die nicht fachgerecht behandelt werden wollen, nicht wahr? Ich kenne sie nicht.\n\nDas Problem mit den Implantaten trat erst nach diesem Gespräch auf, und ich habe überhaupt keine Lust, noch einmal in diese Klinik zu gehen und mich auseinanderzusetzen.\n\nHier noch ein paar interessante Punkte aus der Behandlung in dieser Klinik:\n— Es gab nie kieferorthopädisches Wachs; wenn ein Bogen stach, wurde er einfach abgeschnitten.\n— An der Stelle des fehlenden Zahns auf einer Seite steckt ein Kunststoffröhrchen, das jeden Monat durch ein neues ersetzt werden muss. Temel weigerte sich die ganze Behandlung über, es zu wechseln, und begründete das damit, das Kunststoffröhrchen verhindere angeblich, dass die Zähne auseinanderwandern. Man muss kein Kieferorthopäde sein, um zu verstehen, dass das gelogen ist.\n— Temel hat während der gesamten Behandlung keine Gummizüge verwendet. Aber ganz am Anfang hat er mir eine Zusatzleistung aufgedrängt: den Austausch von zwei Brackets. Angeblich seien sie falsch, weil ihnen die Häkchen fehlten, an denen die Gummizüge befestigt werden. Aber er hat diese Häkchen nie benutzt, genauso wenig wie Gummizüge überhaupt. Und die Position der Brackets war von Anfang an richtig.',
	-- text_tr
	'Rusya\'dan taşındıktan sonra ortodontik tedavime bu klinikte devam ettim, kendi arklarımı yanımda getirdim. Tedaviye uzun bir ara verilmiş olmasına rağmen (altı ay) dişlerim düzgündü ve her şey yolundaydı. Doktor Temel İbrahim tedaviyi yaklaşık altı ayda bitireceğini söyledi ve implantları da kendisinde yaptırmamı önerdi. Tedavi boyunca arkları ve ligatürleri değiştirdi, ancak dişlerin hareketini düzeltmedi. Yaklaşık 2 ay sonra implantları yerleştirdi; oysa ortodontik tedavi bitmeden bunu yapmak doğru değildi (ama ben bunu bilmiyordum). Braketlerin çıkarılması planlanan tarihten 2 ay önce dişlerim kaymaya başladı ve bir tarafta kapanış bozuldu (bu yüzden şimdi çene eklemimde sorun var). O noktada bu doktorun yeterliliğinden ciddi şekilde şüphe etmeye başlamıştım ve başka bir kliniğe konsültasyona gittim. Orada bunun implantlar yüzünden artık düzeltilemeyeceğini söylediler. Ama bu sorun kendiliğinden çözüldü… Başka bir cerrah stabilite testi yaparken implantlardan birini çıkardı, ikincisi için de fazla hareketli olduğunu ve onun da alınması gerektiğini söyledi (şu anda o da alındı). Bu klinik sayesinde sinüs lifting ile kemik grefti yaptırmak zorunda kaldım. İmplantlar yerleştirildikten sonra Temel her şeyin yolunda olup olmadığını yalnızca 1 kez, neredeyse işlemden hemen sonra kontrol etti. Daha sonra implantlardan birinin iyice aşağı indiğini ve diş etini deldiğini hissedince ondan kontrol etmesini rica ettim. Film çekmeden sadece gözle baktı ve her şeyin yolunda olduğunu söyledi.\n\nPeki ya braketler? Temel İbrahim ile konuşma girişimi oldu ve tamamen sonuçsuz kaldı. Sorunun sözde Rusya\'dan gelen arklarda olduğunu ve önceki doktorun suçlu olduğunu söyledi. "Bir şeylerin yanlış gittiğini gördüğünüz hâlde neden hiçbir şey yapmadınız ve söylemediniz?" sorusuna, güya ben kendisinden sadece arkları değiştirmesini istemişim, zavallı adam ne yapsındı diye cevap verdi. Hepimiz profesyonelce tedavi edilmek istemeyen o hastaları biliyoruz, değil mi? Ben bilmiyorum.\n\nİmplant sorunu bu konuşmadan sonra ortaya çıktı ve tekrar bu kliniğe gidip hesaplaşmaya hiç niyetim yok.\n\nİşte bu klinikteki tedaviden birkaç ilginç ayrıntı daha:\n— Hiçbir zaman ortodontik mum olmadı; ark batıyorsa onu basitçe kesiyorlardı.\n— Bir tarafta eksik olan dişin yerinde, her ay yenisiyle değiştirilmesi gereken bir plastik boru duruyor. Temel tedavi boyunca onu değiştirmeyi reddetti ve bunu, plastik borunun güya dişlerin açılmasını engellediğini söyleyerek gerekçelendirdi. Bunun yalan olduğunu anlamak için ortodontist olmaya gerek yok.\n— Temel tedavi boyunca hiç elastik kullanmadı. Ama en başta iki braketin değiştirilmesi şeklinde ek bir hizmeti dayattı. Sözde yanlış braketlermiş, çünkü üzerlerinde elastiklerin takıldığı kancalar yokmuş. Ama o kancaları da, genel olarak elastikleri de hiç kullanmadı. Braketlerin konumu ise baştan itibaren doğruydu.',
	'2026-10-26 12:00:00'
)
ON DUPLICATE KEY UPDATE
	clinic_id = VALUES(clinic_id), doctor_id = VALUES(doctor_id),
	rating = VALUES(rating), status = VALUES(status),
	original_language = VALUES(original_language), original_text = VALUES(original_text),
	text_sr = VALUES(text_sr), text_sr_cyrl = VALUES(text_sr_cyrl),
	text_en = VALUES(text_en), text_ru = VALUES(text_ru),
	text_de = VALUES(text_de), text_tr = VALUES(text_tr),
	published_at = VALUES(published_at);

-- Проверка
SELECT r.id, r.clinic_id, r.doctor_id, r.rating, r.status, r.published_at,
	CHAR_LENGTH(r.text_sr) AS sr, CHAR_LENGTH(r.text_sr_cyrl) AS sr_cyrl,
	CHAR_LENGTH(r.text_en) AS en, CHAR_LENGTH(r.text_ru) AS ru,
	CHAR_LENGTH(r.text_de) AS de, CHAR_LENGTH(r.text_tr) AS tr
FROM reviews r
WHERE r.provider = 'telegram' AND r.provider_review_id = 'tg_anon_temel_dental_20261026';
